-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too)
CREATE FUNCTION authz_int."ms.users:column id, phone, created_at"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "ms"."users";
BEGIN
  IF pg_catalog.row_security_active('"ms"."users"'::pg_catalog.regclass) THEN
    -- the row as the table's own: a partition's columns may be in another order, a table that inherits may have more
    IF TG_RELID = '"ms"."users"'::pg_catalog.regclass THEN v_row := OLD;
    ELSE v_row := pg_catalog.jsonb_populate_record(NULL::"ms"."users", pg_catalog.to_jsonb(OLD)); END IF;
    IF NOT authz_gen."ms.users:column id, phone, created_at:holds"(v_row) THEN
      BEGIN
        v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."ms.users:column id, phone, created_at:why"(v_row) l);
      EXCEPTION WHEN OTHERS THEN
        v_lines := 'no explanation: ' || SQLERRM;
      END;
      RAISE EXCEPTION 'changing id, phone, created_at of ms.users % needs: nobody', OLD."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
        SCHEMA = 'ms', TABLE = 'users', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
    END IF;
  END IF;
  RETURN NEW;
END $f$;

CREATE TRIGGER "authz_update id, phone, created_at" BEFORE UPDATE ON "ms"."users" FOR EACH ROW
  WHEN (OLD."id" IS DISTINCT FROM NEW."id"
     OR OLD."phone" IS DISTINCT FROM NEW."phone"
     OR OLD."created_at" IS DISTINCT FROM NEW."created_at")
  EXECUTE FUNCTION authz_int."ms.users:column id, phone, created_at"();

