CREATE FUNCTION authz_gen."ms.members:column role:items"(p_row "ms"."members") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce((coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = "members"."chat_id")), false),
    coalesce((SELECT authz_int.scope_cmd('ms.members', 'update')), false),
    coalesce(true, false),
    coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = "members"."chat_id"), false),
    coalesce(coalesce((role <> 'owner'), false), false)]
  FROM (SELECT (p_row).*) AS "members";
END;

CREATE FUNCTION authz_gen."ms.members:column role:why"(p_row "ms"."members") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."ms.members:column role:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update role : chat.manage and {role <> ''owner''}  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule ms.members update role'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on ms.members'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'chat.manage';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("members"."chat_id")::text AS id FROM (SELECT (p_row).*) AS "members") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('chat', v_t.id, 'manage') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || '{role <> ''owner''}';
END $f$;

